entries.source:
files.map((relative) => {
    requireString(relative, "MANIFEST_PATH", "manifest relative path");
    if (path.isAbsolute(relative) || relative === ".." || relative.startsWith(`..${path.sep}`)) fail("MANIFEST_PATH", `manifest path escapes root: ${relative}`);
    const normalized = path.normalize(relative);
    if (normalized !== relative || unique.has(relative)) fail("MANIFEST_PATH", `manifest path is duplicate or non-canonical: ${relative}`);
    unique.add(relative);
    const { data, stat } = readOwnedRegularFile(root, path.join(root, relative));
    return { path: relative, bytes: stat.size, sha256: sha256(data) };
  }).sort((a, b) => a.path.localeCompare(b.path))

requiredCanaryNames().map((name) => [name, {
    path: canaryPaths[name],
    existedBefore: name === "control-read" || name === "control-chmod",
    nonce: FIXED.probeId,
  }])

requiredCaseNames().map((name, index) => {
    const policy = requiredCasePolicy(name);
    const intendedBoundary = new Date(Date.parse("2026-07-30T22:10:00.000Z") + index * 60_000).toISOString();
    return [name, {
      nonce: (index + 16).toString(16).padStart(32, "0"),
      ...policy,
      intendedBoundary,
      expected: {
        chatSessionId: FIXED.sessionId,
        taskId: policy.requiresRunBinding ? `task-${String(index + 1).padStart(2, "0")}` : null,
        runId: policy.requiresRunBinding ? `run-${String(index + 1).padStart(2, "0")}` : null,
        turnId: policy.requiresRunBinding ? `turn-${String(index + 1).padStart(2, "0")}` : null,
      },
      mailRowId: name === "N0a-K" ? 77 : null,
    }];
  })

requireNonceInOneUserTurn(parsed.records, expected.runNonce, {
    expectedTurnId: expected.turnId,
    expectedTaskId: expected.taskId,
    expectedRunId: expected.runId,
    label: "scheduled run",
  })
